def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_last = history[-1][1]

    opp_c = sum(1 for _, o in history if o == 'C')
    opp_d = n - opp_c

    if opp_c == 0:
        return 'D'

    w = 12 if n >= 12 else n
    recent_d = sum(1 for _, o in history[-w:] if o == 'D')

    streak = 0
    for _, o in reversed(history):
        if o == 'D':
            streak += 1
        else:
            break

    if n == 99:
        return 'D'

    if n == 98:
        if recent_d >= 4 or opp_d > opp_c:
            return 'D'
        return 'C'

    if recent_d >= 8 or opp_d * 2 >= n:
        if opp_last == 'D':
            return 'D'
        if opp_d > opp_c and recent_d >= 10:
            return 'D'
        return 'C'

    if opp_last == 'D':
        if streak == 1:
            if opp_d > opp_c:
                return 'D'
            if n >= 80 and recent_d >= 2:
                return 'D'
            return 'C'

        if streak == 2:
            return 'D'

        if opp_d > opp_c:
            return 'D'

        if streak >= 6 and recent_d <= 5:
            return 'C'

        if recent_d >= 4:
            return 'D'

        return 'C'

    if opp_d > opp_c:
        return 'D'

    return 'C'
